const sd=$getWorkflowStaticData('global');
sd.runStartedAt=$now.toMillis();
const j=$input.first().json||{};
const q=j.query||{}; const b=j.body||{};
const pick=(k)=>{ const v=(b[k]!==undefined&&b[k]!=='')?b[k]:q[k]; return (v===undefined||v===null)?'':String(v).trim(); };
const list=(v,def)=>{ const s=String(v||'').trim(); return (s?s.split(','):def).map(x=>String(x).trim()).filter(Boolean); };
const cfg={
  client: pick('client'),
  table: pick('table'),
  campaign_url: pick('campaign'),
  sender: pick('sender')||'webhook',
  max_headcount: parseInt(pick('max_headcount')||pick('maxHeadcount'),10)||200,
  country: pick('country')||'US',
  sq_seniority: list(pick('sq_seniority')||pick('sqSeniority'),['C-Suite','VP','Founder','Owner','President','EVP / SVP','Head','Director']),
  sq_function: list(pick('sq_function')||pick('sqFunction'),['Executive','Engineering','R&D','Technology']),
  event_type: pick('event_type')||pick('eventType')||'became_hiring',
  per_company_limit: parseInt(pick('per_company_limit')||pick('perCompanyLimit'),10)||5,
  datasetId: (b.resource&&b.resource.defaultDatasetId)||''
};
const missing=[];
if(!cfg.client) missing.push('client');
if(!cfg.table) missing.push('table');
if(!cfg.campaign_url) missing.push('campaign');
else if(!/^https?:\/\//i.test(cfg.campaign_url)) missing.push('campaign (not a URL)');
cfg.config_ok=(missing.length===0);
cfg.missing=missing;
return [{ json: cfg }];

const r=$input.first().json||{};
const f=r.fields||r;
const name=f['Client']||'';
return [{ json: {
  clientName: name,
  clientRecId: r.id||$('Parse Config').first().json.client||'',
  clientSlug: String(name).toLowerCase().replace(/[^a-z0-9]/g,''),
  slackChannel: f['Slack Channel ID']||'',
  base: f['Clayroots Base ID']||''
}}];

const cfg=$('Parse Config').first().json;
let items = $('Get Scraped Jobs').all().map(i => i.json);
if (items.length === 1 && Array.isArray(items[0])) items = items[0];
const worked = new Set($('Get Worked Domains').all().map(i => { const j = i.json || {}; const d = (j.fields && j.fields.Domain) || j.Domain || ''; return String(d).toLowerCase().trim(); }).filter(Boolean));
const badName = ['staffing','recruit','headhunt','talent acquisition','executive search','sourcer','consulting','outsourcing'];
const badIndustry = ['staffing','recruiting','executive search','venture capital','private equity','venture'];
function has(s, list){ s = String(s || '').toLowerCase(); return list.some(w => s.includes(w)); }
const seen = new Set();
const out = [];
for (const j of items) {
  const country = (j.companyAddress && j.companyAddress.addressCountry) || '';
  if (country && country !== cfg.country) continue;
  if (has(j.companyName, badName) || has(j.jobPosterTitle, badName)) continue;
  if (has(j.industries, badIndustry)) continue;
  const emp = Number(j.companyEmployeesCount || 0);
  if (emp && emp > cfg.max_headcount) continue;
  let domain = String(j.companyWebsite || '').toLowerCase().replace('https://','').replace('http://','').replace('www.','').split('?')[0].split('#')[0].split('/')[0].trim();
  if (!domain) continue;
  if (seen.has(domain)) continue;
  if (worked.has(domain)) continue;
  seen.add(domain);
  out.push({ json: { domain, company: j.companyName || '', headcount: emp, country: country || cfg.country, job_title: j.title || '', job_link: j.link || '', posted_at: j.postedAt || '' } });
}
return out;

const cfg=$('Parse Config').first().json;
const cleanCompany=(nm)=>{if(!nm)return'';let c=String(nm).trim();
const pipe=c.indexOf(' | '); if(pipe>-1) c=c.slice(0,pipe).trim();
const dash=c.indexOf(' - '); if(dash>=3) c=c.slice(0,dash).trim();
c=c.replace(/[®™]/g,'');
for(let i=0;i<2;i++){c=c.replace(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i,'').trim();}
return c.replace(/,+$/,'').trim();};
const companies = {};
for (const i of $('Filter & Qualify Jobs').all()) { companies[i.json.domain] = i.json; }
const TARGET = cfg.campaign_url;
const nowIso = new Date().toISOString();
function pushContact(out, c) {
  const dom = String(c.company_domain || c.domain || '').toLowerCase();
  const co = companies[dom] || {};
  const li = c.linkedin_url || '';
  if (!li) return;
  const role = co.job_title || 'an infrastructure role';
  const posted = co.posted_at ? ' (posted ' + co.posted_at + ')' : '';
  out.push({ json: {
    'Name': c.full_name || ((c.first_name || '') + ' ' + (c.last_name || '')).trim(),
    'first_name': c.first_name || '',
    'last_name': c.last_name || '',
    'LinkedIn URL': li,
    'Domain': dom,
    'Company': cleanCompany(c.company_name || co.company || ''),
    'Email': c.email || '',
    'Event Type': cfg.event_type,
    'Target Campaign': TARGET,
    'Signal Detail': 'Hiring ' + role + posted + '. Decision maker (' + (c.job_title || c.seniority || '') + ') via Apify jobs scrape + Supersoniq. Job: ' + (co.job_link || ''),
    'Intent Status': 'NEW',
    'detected_at': nowIso
  }});
}
const out = [];
for (const it of $('Get Decision Makers').all()) {
  const resp = it.json || {};
  const comps = Array.isArray(resp.results) ? resp.results : [];
  for (const comp of comps) {
    if (Array.isArray(comp.contacts)) { for (const c of comp.contacts) pushContact(out, c); }
    else pushContact(out, comp);
  }
}
return out;

const dnc=new Set();
try{
  const r=$('Get DNC Domains').first().json||{};
  for(const rec of (r.records||[])){ const f=rec.fields||{}; const d=String(f.Domain||f.domain||'').toLowerCase().trim(); if(d) dnc.add(d); }
}catch(e){}
const out=[];
for(const i of $('Build Intent Leads').all()){
  const d=String(i.json['Domain']||'').toLowerCase().trim();
  if(dnc.size && d && dnc.has(d)) continue;
  out.push({ json: i.json });
}
return out;

const cfg=$('Parse Config').first().json||{};
const missing=(cfg.missing||[]).join(', ')||'unknown';
return [{json:{
 'Automation':'Handle Intent Signal',
 'Client': cfg.client?[cfg.client]:[],
 'Status':'Failed',
 'Run at': $now.toISO(),
 'Records In': 0,
 'Records Out': 0,
 'Errors': 1,
 'Target': cfg.table||'(no table)',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Description': '**Run FAILED, head guard tripped before any paid call**\n\n**Missing/invalid params:** '+missing+'\n\n**Required:** client, table, campaign (webhook body or query params on the Apify task URL). Fix and rerun.'
}}];

const sd2=$getWorkflowStaticData('global'); const rs=sd2.runStartedAt||0;
const cfg=$('Parse Config').first().json||{};
let base=''; try{ base=$('Client Vars').first().json.base||''; }catch(e){}
let jobsIn=0; try{ let it=$('Get Scraped Jobs').all().map(i=>i.json); if(it.length===1&&Array.isArray(it[0])) it=it[0]; jobsIn=it.filter(j=>j&&(j.companyName||j.companyWebsite||j.title)).length; }catch(e){}
let qualified=0; try{ qualified=$('Filter & Qualify Jobs').all().map(i=>i.json).filter(j=>j&&j.domain).length; }catch(e){}
let contacts=0; try{ contacts=$('Build Intent Leads').all().map(i=>i.json).filter(j=>j&&j['LinkedIn URL']).length; }catch(e){}
let afterDnc=contacts; try{ afterDnc=$('Apply DNC').all().length; }catch(e){}
let upserted=0;
try{ upserted+=$('Upsert by Email').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
try{ upserted+=$('Upsert by Name+Domain').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
let wfOk=false, wfErrorPages=0;
try{ const w=$('Run Waterfall').first().json||{}; wfOk=!w.error; wfErrorPages=Number(w.errorPages)||0; }catch(e){}
const errs=Math.max(0, afterDnc-upserted);
const totalErrs=(contacts===0)?0:(errs+(wfOk===false?1:0)+wfErrorPages);
const status=totalErrs>0?'Succeeded with errors':'Succeeded';
let lines;
if(contacts===0){
  lines=[
  '**0 contacts found, nothing inserted**',
  '',
  '**Play table:** '+(cfg.table||'(unknown)')+' in '+(base||'(unknown base)'),
  '',
  '**Pipeline**',
  '- **Jobs scraped:** '+jobsIn,
  '- **Companies qualified:** '+qualified,
  '- **Contacts found:** 0',
  '',
  '**Skipped:** DNC gate, upserts and waterfall (nothing to do)'
  ];
}else{
  lines=[
  '**'+upserted+' upserted, '+totalErrs+' error'+(totalErrs===1?'':'s')+'**',
  '',
  '**Play table:** '+(cfg.table||'(unknown)')+' in '+(base||'(unknown base)'),
  '',
  '**Pipeline**',
  '- **Jobs scraped:** '+jobsIn,
  '- **Qualified companies:** '+qualified,
  '- **Decision makers:** '+contacts+(contacts!==afterDnc?' · after DNC gate: '+afterDnc:''),
  '- **Upserted to intent table:** '+upserted+(errs?' · '+errs+' upsert failure(s)':''),
  '',
  '**Waterfall batch fired:** '+(wfOk?'yes (sweeps all rows not done/verifying)':'no / errored')+(wfErrorPages?' · '+wfErrorPages+' error page(s)':''),
  '',
  '**Enrollment:** handled by the daily Add Leads runs'
  ];
}
return [{json:{
 'Automation':'Handle Intent Signal',
 'Client': cfg.client?[cfg.client]:[],
 'Status':status,
 'Run at': $now.toISO(),
 'Records In': (contacts===0?0:afterDnc),
 'Records Out': upserted,
 'Errors': totalErrs,
 'Target': cfg.table||'',
 'Trigger':'event',
 'Execution ID': String($execution.id),
 'Execution Link': 'https://n8n.flowroots.com/workflow/'+$workflow.id+'/executions/'+$execution.id,
 'Duration s': Math.round(($now.toMillis() - (rs||$now.toMillis()))/1000),
 'Description': lines.join('\n')
}}];

let cv=null; try{ cv=$('Client Vars').first().json; }catch(e){}
if(!cv||!cv.clientSlug) return [];
const cfg=$('Parse Config').first().json||{};
let upserted=0;
try{ upserted+=$('Upsert by Email').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
try{ upserted+=$('Upsert by Name+Domain').all().map(i=>i.json).filter(j=>j&&j.id).length; }catch(e){}
return [{ json: {
  recordId: cv.clientRecId||cfg.client||'',
  clientSlug: cv.clientSlug||'',
  base: cv.base||'', table: cfg.table||'', campaign_url: cfg.campaign_url||'', sender: cfg.sender||'webhook',
  upserted: upserted
}}];
